@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container" @ref="_containerRef">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div class="infinite-scroll-sentinel" @ref="_sentinelRef">
            @if (_isLoading)
            {
                <div class="infinite-scroll-loading">
                    <div class="spinner-border spinner-border-sm" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter]
    public bool HasMore { get; set; }

    /// <summary>Distance in pixels from the bottom edge at which loading triggers.</summary>
    [Parameter]
    public int ThresholdPx { get; set; } = 100;

    private ElementReference _containerRef;
    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;
    private bool _initialized;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-91f620556b754cdf87c2ee1a4d0dd284/infinite-scroll.js");

            await SetupObserver();
            _initialized = true;
        }
        else if (_initialized && HasMore)
        {
            // Re-observe after new items render (sentinel element may have been re-created)
            await SetupObserver();
        }
    }

    private async Task SetupObserver()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("observe", _sentinelRef, _containerRef, _dotNetRef, ThresholdPx);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("disconnect");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already gone — safe to ignore.
            }
        }

        _dotNetRef?.Dispose();
    }
}

.infinite-scroll-container {
    overflow-y: auto;
    max-height: 80vh;
}

.infinite-scroll-loading {
    display: flex;
    justify-content: center;
    padding: 1rem;
}

let observer = null;

export function observe(sentinelElement, containerElement, dotNetRef, thresholdPx) {
    disconnect();

    observer = new IntersectionObserver(
        (entries) => {
            const entry = entries[0];
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync("OnSentinelVisible");
            }
        },
        {
            root: containerElement,
            rootMargin: `0px 0px ${thresholdPx}px 0px`,
        }
    );

    observer.observe(sentinelElement);
}

export function disconnect() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

